def preferencias_musica():
    return QSettings("VighnaStudy", "MusicaAmbienteB41")


def musica_habilitada():
    raw = str(preferencias_musica().value(CHAVE_ATIVA, True)).strip().lower()
    return raw not in ("false", "0", "off", "no", "")


def alterar_musica_habilitada(nova: bool):
    cfg = preferencias_musica()
    cfg.setValue(CHAVE_ATIVA, bool(nova))
    cfg.sync()


def garantir_musica():
    cache = Path(os.environ.get("LOCALAPPDATA") or tempfile.gettempdir())
    arquivo = cache / "VighnaStudy" / "Cache" / "musica_b42" / AUDIO_NOME
    try:
        if arquivo.is_file() and hashlib.sha256(arquivo.read_bytes()).hexdigest() == AUDIO_SHA:
            return arquivo
        dados = zlib.decompress(base64.b85decode(AUDIO_EMBUTIDO))
        if hashlib.sha256(dados).hexdigest() != AUDIO_SHA:
            raise ValueError("SHA-256 da trilha Órbita de Cristal divergente")
        arquivo.parent.mkdir(parents=True, exist_ok=True)
        temp = arquivo.with_name(arquivo.name + f".{os.getpid()}.tmp")
        temp.write_bytes(dados)
        os.replace(temp, arquivo)
        return arquivo
    except (OSError, ValueError, zlib.error) as exc:
        print("B42: audio indisponivel:", exc, file=sys.stderr)
        return None


class ReprodutorOrbitaB42(QObject):
    """Controlador Qt + fallback MCI nativo; instâncias em processos distintos."""
    def __init__(self, parent=None):
        super().__init__(parent)
        self._efeito = None
        self._backend = None
        self._ativo = False
        self._em_execucao = False
        self._alias = "vighna_orbita_" + str(os.getpid())
        self._mci_aberto = False
        self._mci_pausado = False
        self._arquivo = None
        self._repetir = QTimer(self)
        self._repetir.setInterval(400)
        self._repetir.timeout.connect(self._checar_loop)

    def _mci(self, comando, consulta=False):
        retorno = ctypes.create_unicode_buffer(120) if consulta else None
        try:
            rc = ctypes.windll.winmm.mciSendStringW(
                comando, retorno, len(retorno) if retorno is not None else 0, None
            )
            if rc != 0:
                return None
            return retorno.value if retorno is not None else ""
        except (AttributeError, OSError):
            return None

    def iniciar(self):
        self._ativo = True
        self.reproduzir()

    def reproduzir(self):
        if not self._ativo or self._em_execucao:
            return
        if self._arquivo is None:
            self._arquivo = garantir_musica()
            if self._arquivo is None:
                return
        if self._backend == "qt" and self._efeito is not None:
            self._efeito.play()
            self._em_execucao = True
            return
        if self._backend == "mci" and self._mci_aberto:
            cmd = "resume " + self._alias if self._mci_pausado else "play " + self._alias
            if self._mci(cmd) is None:
                if self._mci("play " + self._alias + " from 0") is None:
                    return
            self._mci_pausado = False
            self._repetir.start()
            self._em_execucao = True
            return
        if QSoundEffect is not None:
            try:
                self._efeito = QSoundEffect(self)
                self._efeito.setSource(QUrl.fromLocalFile(str(self._arquivo)))
                self._efeito.setLoopCount(QSoundEffect.Infinite)
                self._efeito.setVolume(0.64)
                self._efeito.statusChanged.connect(self._qt_status)
                if self._efeito.status() != QSoundEffect.Status.Error:
                    self._backend = "qt"
                    self._efeito.play()
                    self._em_execucao = True
                    QTimer.singleShot(1500, self._verificar_qt)
                    return
            except (RuntimeError, OSError, AttributeError):
                self._backend = None
        self._reproduzir_mci()

    def _qt_status(self):
        try:
            # Um status tardio do Qt não pode criar outro player MCI depois
            # de uma pausa ou quando o backend MCI já está em uso.
            if (self._backend == "qt" and self._efeito is not None
                    and self._efeito.status() == QSoundEffect.Status.Error):
                self._em_execucao = False
                self._backend = None
                try:
                    self._efeito.stop()
                except (RuntimeError, AttributeError):
                    pass
                if self._ativo:
                    self._reproduzir_mci()
        except (RuntimeError, AttributeError):
            pass

    def _verificar_qt(self):
        if not self._ativo or self._backend != "qt" or self._efeito is None:
            return
        try:
            if self._efeito.status() == QSoundEffect.Status.Error or (
                self._efeito.isLoaded() and not self._efeito.isPlaying()
            ):
                self._efeito.stop()
                self._em_execucao = False
                self._backend = None
                self._reproduzir_mci()
        except (RuntimeError, AttributeError):
            pass

    def _reproduzir_mci(self):
        if sys.platform != "win32" or self._arquivo is None or not self._ativo:
            return
        if self._backend == "mci" and self._em_execucao:
            return
        # Fallback exclusivo: nunca manter QSoundEffect e MCI tocando juntos.
        self._backend = "mci"
        if self._efeito is not None:
            try:
                self._efeito.stop()
                self._efeito.setSource(QUrl())
            except (RuntimeError, AttributeError):
                pass
        if not self._mci_aberto:
            if self._mci('open "' + str(self._arquivo) + '" type waveaudio alias ' + self._alias) is None:
                return
            self._mci_aberto = True
        self._backend = "mci"
        if self._mci("play " + self._alias + " from 0") is None:
            return
        self._mci_pausado = False
        self._em_execucao = True
        self._repetir.start()

    def _checar_loop(self):
        if self._backend != "mci" or not self._ativo or not self._em_execucao:
            return
        if self._mci("status " + self._alias + " mode", consulta=True) == "stopped":
            self._mci("play " + self._alias + " from 0")

    def pausar(self):
        self._ativo = False
        self._repetir.stop()
        # Parar SEMPRE ambos os backends, inclusive após fallback assíncrono.
        if self._efeito is not None:
            try:
                self._efeito.stop()
            except RuntimeError:
                pass
        if self._mci_aberto:
            self._mci("pause " + self._alias)
            self._mci_pausado = True
        self._em_execucao = False

    def fechar(self):
        self.pausar()
        if self._mci_aberto:
            self._mci("stop " + self._alias)
            self._mci("close " + self._alias)
            self._mci_aberto = False


class MusicaAmbienteB42(QObject):
    """Um botão real na Home original, com silêncio durante qualquer bateria."""
    def __init__(self, janela, home):
        super().__init__(janela)
        self._janela = janela
        self._home = home
        self._app = QApplication.instance()
        self.habilitada = musica_habilitada()
        self._iniciado = False
        self._fechado = False
        self._player = ReprodutorOrbitaB42(self)
        # Iniciar Home somente quando o splash terminar. As duas janelas
        # executam em processos distintos, por isso um QTimer faz a passagem.
        self._aguardar_splash = QTimer(self)
        self._aguardar_splash.setInterval(250)
        self._aguardar_splash.timeout.connect(self._concluir_passagem_splash)
        self._botao = QPushButton(home)
        self._botao.setObjectName("b42MusicOriginalToggle")
        self._botao.setCursor(Qt.PointingHandCursor)
        self._botao.setFocusPolicy(Qt.StrongFocus)
        self._botao.setAccessibleName("Ligar ou desligar Órbita de Cristal")
        self._botao.setStyleSheet(
            'QPushButton {color:#eaf8ff;background:#0e3048;'
            'border:1px solid #3db9d3;border-radius:9px;padding:5px;'
            'font-size:13pt;font-weight:700;}'
            'QPushButton:hover {background:#19506a;border-color:#ffd38a;}'
            'QPushButton:focus {border:2px solid #ffd38a;}'
        )
        self._botao.clicked.connect(self.alternar)
        home.installEventFilter(self)
        if self._app is not None:
            self._app.installEventFilter(self)
            self._app.aboutToQuit.connect(self.finalizar)
        self.sincronizar_controles()

    def _bateria_aberta(self):
        if self._app is None:
            return False
        for win in self._app.topLevelWidgets():
            if type(win).__name__ != 'JanelaResolverQuestoes':
                continue
            try:
                if win.isVisible() or win.isMinimized():
                    return True
            except RuntimeError:
                pass
        return False

    def _pode_tocar(self):
        return (self._iniciado and not self._fechado and self.habilitada
                and not splash_ativo_neste_processo()
                and not self._bateria_aberta())

    def _concluir_passagem_splash(self):
        if self._fechado:
            self._aguardar_splash.stop()
            return
        if splash_ativo_neste_processo():
            self._player.pausar()
            return
        self._aguardar_splash.stop()
        # Preferência escolhida no splash, não o valor antigo da Home.
        self.habilitada = musica_habilitada()
        self.sincronizar()

    def _posicionar(self):
        self._botao.setGeometry(max(12, self._home.width()-69), max(12,self._home.height()-53), 43, 35)

    def sincronizar_controles(self):
        self._posicionar()
        self._botao.setVisible(self._janela.telas.currentWidget() is self._home)
        self._botao.setText('♫' if self.habilitada else '♪')
        self._botao.setToolTip(
            'Pausar Órbita de Cristal' if self.habilitada else 'Reproduzir Órbita de Cristal'
        )
        if self._botao.isVisible():
            self._botao.raise_()

    def iniciar(self):
        if self._fechado:
            return
        self._iniciado = True
        # Durante o splash, o único dono do áudio é o processo de inicialização.
        self.habilitada = musica_habilitada()
        if splash_ativo_neste_processo():
            self._aguardar_splash.start()
        self.sincronizar()

    def alternar(self, *_args):
        self.habilitada = not self.habilitada
        alterar_musica_habilitada(self.habilitada)
        self.sincronizar()

    def sincronizar(self, *_args):
        if self._fechado:
            return
        if self._iniciado and splash_ativo_neste_processo():
            if not self._aguardar_splash.isActive():
                self._aguardar_splash.start()
        self.sincronizar_controles()
        if self._pode_tocar():
            self._player.iniciar()
        else:
            self._player.pausar()

    def eventFilter(self,objeto,evento):
        try:
            tipo=evento.type()
            if objeto is self._home and tipo in (QEvent.Resize,QEvent.Show):
                self._posicionar()
            elif (type(objeto).__name__ == 'JanelaResolverQuestoes'
                  and tipo in (QEvent.Show,QEvent.Hide,QEvent.Close,QEvent.WindowStateChange)):
                if tipo == QEvent.Show:
                    self._player.pausar()
                QTimer.singleShot(0,self.sincronizar)
        except (RuntimeError,AttributeError):
            pass
        return False

    def finalizar(self):
        if self._fechado:
            return
        self._fechado = True
        self._aguardar_splash.stop()
        self._player.fechar()
